  st.textContent = `:root{--accent:${a[1]};--accent-soft:${a[2]};--info-soft:${a[2]}}@media(prefers-color-scheme:dark){:root:not([data-theme="light"]){--accent:${a[3]};--accent-soft:${a[4]};--info-soft:${a[4]}}}:root[data-theme="dark"]{--accent:${a[3]};--accent-soft:${a[4]};--info-soft:${a[4]}}`;
