function modSave(m, f) {
  const d = MODSET[m], secs = d.ext ? EXT[d.ext]() : d.secs, out = {};
  secs.flatMap(s => s[2]).forEach(([k, label, type]) => { const el = f.querySelector(`[name="${k}"]`); if (type === 'bool') out[k] = el.checked; else { let v = el.value.trim(); if (type === 'number') { if (v === '' || !(+v >= 0)) throw new Error(label + ' must be 0 or more.'); v = +v; } out[k] = v; } });
  if (d.ext) DB[EXT_STORE[d.ext][0]] = { ...(DB[EXT_STORE[d.ext][0]] || {}), ...out }; else DB.cfg.mod[m] = out;
  return d.t + ' settings saved.';
}

