function settingsShow(page, mode, id) {
  CUR = { mod: 'settings', sub: '' };
  if (!mode) return setHome();
  if (mode === 'role') return SETV.role(decodeURIComponent(id || ''));
  if (PLANNED[mode]) return setShell(mode, PLANNED[mode][0], '', card('Planned for phase 2', `<div class="card-b"><p style="margin:0">${esc(PLANNED[mode][1])}</p></div>`));
  if (mode.startsWith('m_')) return modPage(mode.slice(2));
  return SETV[mode] ? SETV[mode]() : setShell(mode, 'Not found', '', '<div class="card empty">This settings page does not exist.</div>');
}

